# Attribute Highight 
'attribute' = { fg = 'greenhl', modifiers=['bold'] }

# Constructor Highlight
'constructor' = { fg = 'greenhl', modifiers = ['bold'] }

# Constant Highlight
# 'constant.builtin' = { fg = 'magenta' }
# 'constant.builtin.boolean' = { fg = 'yellow' }
# 'constant.character' = {}
# 'constant.character.escape' = {}
'constant' = { fg = 'green100', modifiers = ['bold'] }
# 'constant.numeric' = { fg = 'orange' }
# 'constant.numeric.float' = {}
# 'constant.numeric.integer' = {}

# String Highlights
'string' = { fg = 'green', modifiers = ['italic', 'bold'] }
# 'string.regexp' = {}
'string.special' = {fg = 'green300'}
# 'string.special.path' = {}
# 'string.special.url' = {}
# 'string.special.symbol' = {}

# Comment Highlights
# 'comment.block.documentation' = { fg = 'green', modifiers = ['italic'] }
# 'comment.block' = { fg = 'green', modifiers = ['italic'] }
'comment' = { fg = 'green900', modifiers = ['italic'] }
# 'comment.line' = {}
# 'comment.line.documentation' = {}
# 'comment.unused' = {}

# Variable Highlights
'variable' = { fg = 'green300', modifiers = ['italic', 'bold'] }
# 'variable.builtin' = { fg = 'yellow' }
# 'variable.parameter' = { fg = 'white' }
# 'variable.other' = { fg = 'blue' }
'variable.other.member' = { fg = 'greenhl', modifiers = ['italic'] }
'variable.other.member.private' = { fg = 'greenhl' }

# Label Highlights
'label' = { fg = 'greenhl', modifiers = ['bold', 'italic'] }

# Punctuation Highlights
'punctuation' = { fg = 'greenhl', modifiers = ['bold'] }
# 'punctuation.bracket' = { fg = 'red' }
# 'punctuation.delimiter' = { fg = 'red', modifiers = ['bold'] }
# 'punctuation.special' = { fg = 'red' }

# Keyword Highlights
'keyword' = { fg = 'green300', modifiers = ['bold', 'italic'] }
# 'keyword.control' = {}
# 'keyword.control.conditional' = {}
# 'keyword.control.repeat' = {}
# 'keyword.control.import' = {}
# 'keyword.control.return' = {}
# 'keyword.control.exception' = {}

# Operator Highlights
'operator' = { fg = 'green', modifiers = ['bold'] }

# Directive Highlights (and,or,not)
'directive' = { fg = 'greenhl' }

# Special Highlights 
'special' = { fg = 'greenhl' }

# Namespace Highlights
'namespace' = { fg = 'green500', modifiers = ['italic'] }

# Function Highlights 
'function' = { fg = 'green100', modifiers = ['italic'] }
# 'function.builtin' = { fg = 'blue' }
# 'function.method' = { fg = 'white' }
# 'function.method.private' = { fg = 'red' }
# 'function.macro' = {}
# 'function.special' = {}

# Tag Highlights 
'tag' = { fg = 'green700', modifiers = ['italic','bold'] }

# Type Highlights 
'type' = { fg = 'green300', modifiers = ['italic']}
# 'type.bultin' = { fg = '' }
# 'type.parameter' = { fg = '' }
# 'type.enum' = { fg = '' }
# 'type.enum.variant' = { fg = '' }

# Markup Highlights 
'markup.bold' = { fg = 'green300', modifiers = ['bold'] }
'markup.italic' = { fg = 'green100', modifiers = ['italic'] }
# 'markup.strikethrough' = { modifiers = ['crossed_out'] }
'markup.heading' = { fg = 'green100', modifiers = ['bold'] }
# 'markup.heading.marker' = { fg = 'red' }
# 'markup.heading.1' = { fg = 'red' }
# 'markup.heading.2' = { fg = 'red' }
# 'markup.heading.3' = { fg = 'red' }
# 'markup.heading.4' = { fg = 'red' }
# 'markup.heading.5' = { fg = 'red' }
# 'markup.heading.6' = { fg = 'red' }
'markup.link' = { fg = 'green100' }
# 'markup.link.url' = { fg = 'magenta' }
# 'markup.link.text' = { fg = 'orange' }
# 'markup.link.label' = { fg = 'green' }
'markup.list' = { fg = 'green300', modifiers = ['bold'] }
# 'markup.list.unnumbered' = { fg = 'red' }
# 'markup.list.numbered' = { fg = 'red' }
# 'markup.list.checked' = { fg = 'red' }
# 'markup.list.unchecked' = { fg = 'red' }
'markup.quote' = { fg = 'green', bg = 'base01', modifiers = ['italic'] }
'markup.raw' = { fg = 'green100', bg='base02'}
# 'markup.raw.block' = { fg = 'green', bg = 'base01' }
# 'markup.raw.inline' = { fg = 'green', bg = 'base01' }

# Diff Highlights
# 'diff.delta.conflict' = { fg = 'green100' }
'diff.delta' = { fg = 'green' }
# 'diff.delta.gutter' = { fg = 'white' }
# 'diff.delta.moved' = { fg = 'blue' }
'diff.minus' = { fg = 'green' }
# 'diff.minus.gutter' = { fg = 'red' }
'diff.plus' = { fg = 'green' }
# 'diff.plus.gutter' = { fg = 'green' }


