'ui.highlight.frameline' = { fg = 'greenhl', bg = 'base03' }
'ui.linenr' = { fg = 'green', bg = 'base01' }
'ui.linenr.selected' = { fg = 'green100', bg = 'base01', modifiers = ['bold'] }
