'ui.virtual.ruler' = { bg = 'base01' }
# 'ui.virtual.whitespace' = { fg = 'base02' }
# 'ui.virtual.wrap' = { fg = 'base02' }
'ui.window' = { fg = 'greenhl' }

'error' = { fg = 'green100', modifiers = ['bold'] }
'hint' = { fg = 'green300', modifiers = ['bold'] }
'info' = { fg = 'green500', modifiers = ['bold'] }
'warning' = { fg = 'green700', modifiers = ['bold']}

# 'diagnostic' = {}
"diagnostic.deprecated" = { modifiers = ["crossed_out"] }
'diagnostic.error' = { underline = { color = 'green100', style = "curl" } }
'diagnostic.hint' = { underline = { color = 'green300', style = "curl" } }
'diagnostic.info' = { underline = { color = 'green500', style = "curl" } }
"diagnostic.unnecessary" = { modifiers = ["dim"] }
'diagnostic.warning' = { underline = { color = 'green700', style = "curl" } }
